","jsContent":"var submitButton = document.querySelector('#braintree-submit-button');
var errorBox = document.querySelector('#braintree-error');

function clearError() {
  errorBox.textContent = '';
}

function showError(message) {
  errorBox.textContent = message || 'The payment could not be started. Please try again.';
}

function submitNonce(payload, handlers) {
  var submitBody = {
    additionalData: [
      { key: 'nonce', value: payload.nonce },
      { key: 'paymentType', value: payload.type }
    ]
  };

  if (handlers) {
    submitBody.submitSuccess = handlers.success;
    submitBody.submitPending = handlers.pending;
    submitBody.submitFailure = handlers.failure;
    submitBody.submitCancel = handlers.cancel;
  }

  window.Opf.payments.checkout.submit(submitBody);
}

braintree.client.create({
  authorization: OpfContext.customFields.clientToken
}, function (clientErr, clientInstance) {
  if (clientErr) {
    console.error(clientErr);
    showError();
    return;
  }

  braintree.hostedFields.create({
    client: clientInstance,
    styles: {
      input: { 'font-size': '1rem', 'font-family': 'inherit', color: '#32325d' },
      '::placeholder': { color: '#8898aa' },
      ':focus': { color: '#32325d' },
      '.invalid': { color: '#bb0000' }
    },
    fields: {
      number: { container: '#bt-number', placeholder: '************1111' },
      expirationDate: { container: '#bt-expiration', placeholder: 'MM/YY' },
      cvv: { container: '#bt-cvv', placeholder: '123' }
    }
  }, function (hostedFieldsErr, hostedFieldsInstance) {
    if (hostedFieldsErr) {
      console.error(hostedFieldsErr);
      showError();
      return;
    }

    if (submitButton.getAttribute('data-bt-bound') === 'true') {
      return;
    }
    submitButton.setAttribute('data-bt-bound', 'true');

    submitButton.addEventListener('click', function () {
      clearError();
      hostedFieldsInstance.tokenize(function (tokenizeErr, payload) {
        if (tokenizeErr) {
          console.error(tokenizeErr);
          showError('Please check your card details and try again.');
          return;
        }
        submitNonce(payload);
      });
    });
  });

  var configEl = document.querySelector('#braintree-config');
  var payLaterEnabled = !!configEl && configEl.getAttribute('data-paylater') === 'true';
  var merchantPrefix = configEl ? configEl.getAttribute('data-merchant-prefix') : '';
  var billingCountry = (OpfContext.billingAddress && OpfContext.billingAddress.country) || '';

  function createPayPalCheckout(options, callback) {
    braintree.paypalCheckout.create(options, function (createErr, instance) {
      if (createErr && options.merchantAccountId) {
        console.warn('PayPal Checkout unavailable for merchant account ' + options.merchantAccountId + '; falling back to the gateway default.', createErr);
        createPayPalCheckout({ client: options.client }, callback);
        return;
      }
      callback(createErr, instance);
    });
  }

  var paypalOptions = { client: clientInstance };

  if (merchantPrefix) {
    paypalOptions.merchantAccountId = merchantPrefix + String(OpfContext.currency).toLowerCase();
  }

  createPayPalCheckout(paypalOptions, function (paypalErr, paypalCheckoutInstance) {
    if (paypalErr) {
      console.error(paypalErr);
      return;
    }

    function renderButton(fundingSource, container, eligibleOnly) {
      if (!fundingSource) {
        return;
      }

      var button = paypal.Buttons({
        fundingSource: fundingSource,
        createOrder: function () {
          return paypalCheckoutInstance.createPayment({
            flow: 'checkout',
            amount: OpfContext.amount,
            currency: OpfContext.currency,
            intent: 'authorize'
          });
        },
        onApprove: function (data) {
          return new Promise(function (resolve, reject) {
            paypalCheckoutInstance.tokenizePayment(data, function (tokenizeErr, payload) {
              if (tokenizeErr) {
                console.error(tokenizeErr);
                showError('PayPal could not complete the payment. Please try again.');
                reject(tokenizeErr);
                return;
              }

              submitNonce(payload, {
                success: resolve,
                pending: resolve,
                failure: function (response) {
                  console.error(response);
                  showError('PayPal could not complete the payment. Please try again.');
                  reject(response);
                },
                cancel: reject
              });
            });
          });
        },
        onError: function (buttonErr) {
          console.error(buttonErr);
          showError('PayPal could not complete the payment. Please try again.');
        }
      });

      if (eligibleOnly && !button.isEligible()) {
        console.warn('[braintree] funding source "' + fundingSource + '" reports isEligible() === false; button suppressed. currency=' + OpfContext.currency);
        return;
      }

      var containerEl = document.querySelector(container);
      if (containerEl) {
        containerEl.innerHTML = '';
      }

      button.render(container);
